"""Grounding check: do benchmark models really SEE our media when run on Kaggle?

Image: a real frame from the H2S explainer (its labels include NRB, OUTCOMPETE, ORGANIC CARBON).
Video: the published H2S short on YouTube (opens on a title question about sewer pipes).
A model passes only if it reports content that is actually in the media.
"""
import kaggle_benchmarks as kbench
from kaggle_benchmarks.content_types import images, videos

FRAME_B64 = ""
SHORT_URL = "https://www.youtube.com/shorts/MdX0ydBJYxI"


@kbench.task(name="hrsu-media-grounding", description="Does the model see our frame and video?")
def media_grounding(llm) -> None:
    txt = llm.prompt("List every word of text visible in this image, exactly, comma separated. "
                     "If you cannot see an image, reply NO IMAGE.",
                     image=images.from_base64(FRAME_B64, format="jpeg"))
    up = txt.upper()
    kbench.assertions.assert_true("NRB" in up and "OUTCOMPETE" in up,
                                  expectation="image read: " + txt[:300])
    vid = llm.prompt("Watch this video. Quote the on-screen text of its very first frame, and name "
                     "the two kinds of bacteria it shows. If you cannot watch the video, reply NO VIDEO.",
                     video=videos.from_url(SHORT_URL))
    vu = vid.upper()
    kbench.assertions.assert_true(("SEWER" in vu or "PIPE" in vu) and "NITRATE" in vu,
                                  expectation="video read: " + vid[:400])


media_grounding.run(kbench.llm)
